   468→    let group2 = registry.new_emode_group(0, scenario.ctx());
   469→
   470→    assert!(group1 == 0, 0);
   471→    assert!(group2 == 1, 1);
   472→
   473→    // Create params for TestCoinA in group1
   474→    let params_a_g1 = new_emode_params(
   475→        float::from_quotient(80, 100),  // collateral_factor: 0.8
   476→        float::from_quotient(85, 100),  // liquidation_factor: 0.85
   477→        float::from_quotient(5, 100),   // liquidation_incentive: 0.05
   478→        1000000000,                      // max_borrow_amount: 1B
   479→        float::from_quotient(110, 100), // borrow_weight: 1.1
   480→        float::from_quotient(1, 1000),  // flash_loan_fee_rate: 0.001
   481→        limiter::create_new_limiter_change(5000000000, 86400, 3600), // deposit_limiter: 5B per day, 1hr segments
   482→        limiter::create_new_limiter_change(2000000000, 86400, 3600), // borrow_limiter: 2B per day, 1hr segments
   483→    );
   484→
   485→    // Create params for TestCoinB in group2 with DIFFERENT values
   486→    let params_b_g2 = new_emode_params(
   487→        float::from_quotient(70, 100),  // collateral_factor: 0.7 (different)
   488→        float::from_quotient(75, 100),  // liquidation_factor: 0.75 (different)
   489→        float::from_quotient(10, 100),  // liquidation_incentive: 0.10 (different)
   490→        500000000,                       // max_borrow_amount: 500M (different)
   491→        float::from_quotient(120, 100), // borrow_weight: 1.2 (different)
   492→        float::from_quotient(2, 1000),  // flash_loan_fee_rate: 0.002 (different)
   493→        limiter::create_new_limiter_change(3000000000, 86400, 3600), // deposit_limiter: 3B per day (different)
   494→        limiter::create_new_limiter_change(1000000000, 86400, 3600), // borrow_limiter: 1B per day (different)
   495→    );
   496→
   497→    // Support assets in different groups
   498→    registry.support_asset<TestCoinA>(group1, params_a_g1, scenario.ctx());
   499→    registry.support_asset<TestCoinB>(group2, params_b_g2, scenario.ctx());
   500→
   501→    // Verify TestCoinA in group1
   502→    let type_name_a = std::type_name::with_defining_ids<TestCoinA>();
   503→    assert!(registry.is_support(group1, type_name_a), 2);
   504→    let emode_a = registry.borrow_emode_group(group1).borrow_emode(type_name_a);
   505→
   506→    let collateral_a = emode_a.collateral();
   507→    assert!(collateral_a.collateral_factor().eq(float::from_quotient(80, 100)), 3);
   508→    assert!(collateral_a.liquidation_factor().eq(float::from_quotient(85, 100)), 4);
   509→    assert!(collateral_a.liquidation_incentive().eq(float::from_quotient(5, 100)), 5);
   510→
   511→    let borrow_a = emode_a.borrow();
   512→    assert!(borrow_a.max_borrow_amount() == 1000000000, 6);
   513→    assert!(borrow_a.borrow_weight().eq(float::from_quotient(110, 100)), 7);
   514→
   515→    let flashloan_a = emode_a.flash_loan();
   516→    assert!(flashloan_a.fee_rate().eq(float::from_quotient(1, 1000)), 8);
   517→
   518→    // Verify TestCoinB in group2 has DIFFERENT values
   519→    let type_name_b = std::type_name::with_defining_ids<TestCoinB>();
   520→    assert!(registry.is_support(group2, type_name_b), 9);
   521→    let emode_b = registry.borrow_emode_group(group2).borrow_emode(type_name_b);
   522→
   523→    let collateral_b = emode_b.collateral();
   524→    assert!(collateral_b.collateral_factor().eq(float::from_quotient(70, 100)), 10);
   525→    assert!(collateral_b.liquidation_factor().eq(float::from_quotient(75, 100)), 11);
   526→    assert!(collateral_b.liquidation_incentive().eq(float::from_quotient(10, 100)), 12);
   527→
   528→    let borrow_b = emode_b.borrow();
   529→    assert!(borrow_b.max_borrow_amount() == 500000000, 13);
   530→    assert!(borrow_b.borrow_weight().eq(float::from_quotient(120, 100)), 14);
   531→
   532→    let flashloan_b = emode_b.flash_loan();
   533→    assert!(flashloan_b.fee_rate().eq(float::from_quotient(2, 1000)), 15);
   534→
   535→    // Verify that values are indeed different between groups
   536→    assert!(!collateral_a.collateral_factor().eq(collateral_b.collateral_factor()), 16);
   537→    assert!(!collateral_a.liquidation_factor().eq(collateral_b.liquidation_factor()), 17);
   538→    assert!(!collateral_a.liquidation_incentive().eq(collateral_b.liquidation_incentive()), 18);
   539→    assert!(borrow_a.max_borrow_amount() != borrow_b.max_borrow_amount(), 19);
   540→    assert!(!borrow_a.borrow_weight().eq(borrow_b.borrow_weight()), 20);
   541→    assert!(!flashloan_a.fee_rate().eq(flashloan_b.fee_rate()), 21);
   542→
   543→    // Verify TestCoinA is NOT in group2 and TestCoinB is NOT in group1
   544→    assert!(!registry.is_support(group2, type_name_a), 22);
   545→    assert!(!registry.is_support(group1, type_name_b), 23);
   546→
   547→    scenario.end();
   548→    std::unit_test::destroy(registry);
   549→}
