module protocol::generic_store;

use std::type_name::{Self, TypeName};
use protocol::wit_table::{Self, WitTable};

public struct GenericCoinTypeStorage<phantom T: store> has store {
    table: WitTable<GenericTable, TypeName, T>,
}

// ============== Constructor =============
public(package) fun new<T: store>(ctx: &mut TxContext): GenericCoinTypeStorage<T> {
    let table = wit_table::new<GenericTable, TypeName, T>(GenericTable {}, true, ctx);
    GenericCoinTypeStorage { table }
}

// =============== Getter Functions =============
public(package) fun supports<T: store, CoinType>(self: &GenericCoinTypeStorage<T>): bool {
    let name = type_name::with_defining_ids<CoinType>();
    self.table.contains(name)
}

public(package) fun supports_type<T: store>(self: &GenericCoinTypeStorage<T>, name: TypeName): bool {
    self.table.contains(name)
}

public(package) fun is_empty<T: store>(self: &GenericCoinTypeStorage<T>):bool {
    self.table.is_empty()
}

public(package) fun keys<T: store>(self: &GenericCoinTypeStorage<T>): vector<TypeName> {
    self.table.keys()
}

public(package) fun load<T: store, CoinType>(self: &GenericCoinTypeStorage<T>): &T {
    let name = type_name::with_defining_ids<CoinType>();
    self.table.borrow(name)
}

public(package) fun load_by_type<T: store>(self: &GenericCoinTypeStorage<T>, name: TypeName): &T {
    self.table.borrow( name)
}

// ============== Update Functions ===============
public(package) fun store<T: store, CoinType>(self: &mut GenericCoinTypeStorage<T>, item: T) {
    let name = type_name::with_defining_ids<CoinType>();
    wit_table::add(GenericTable {}, &mut self.table, name, item);
}

public(package) fun remove<T: store, CoinType>(self: &mut GenericCoinTypeStorage<T>): T {
    let name = type_name::with_defining_ids<CoinType>();
    wit_table::remove(GenericTable {}, &mut self.table, name)
}

public(package) fun load_mut_by_type<T: store>(self: &mut GenericCoinTypeStorage<T>, type_name: TypeName): &mut T {
    wit_table::borrow_mut(GenericTable {}, &mut self.table, type_name)
}

// ============== Internal =============

public struct GenericTable has drop {}

